dashboard.definition:
{
    "title": "Sicherheit und Datenschutz",
    "description": "Sicherheitslage: KIS-Zugriffsprotokoll, Windows-Anmeldungen, ISE, Logins auf Netzwerkgeraeten und betroffene Cisco-Geraete",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Zeitraum",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        },
        "input_dept": {
            "type": "input.dropdown",
            "title": "Abteilung",
            "options": {
                "items": [
                    {
                        "label": "Alle Abteilungen",
                        "value": "*"
                    },
                    {
                        "label": "Innere Medizin (INN)",
                        "value": "INN"
                    },
                    {
                        "label": "Kardiologie (KAR)",
                        "value": "KAR"
                    },
                    {
                        "label": "Neurologie (NEU)",
                        "value": "NEU"
                    },
                    {
                        "label": "Onkologie (ONK)",
                        "value": "ONK"
                    },
                    {
                        "label": "Allgemeinchirurgie (CHI)",
                        "value": "CHI"
                    },
                    {
                        "label": "Unfallchirurgie/Orthopaedie (UCH)",
                        "value": "UCH"
                    },
                    {
                        "label": "Urologie (URO)",
                        "value": "URO"
                    },
                    {
                        "label": "HNO",
                        "value": "HNO"
                    },
                    {
                        "label": "Anaesthesie/OP (ANA)",
                        "value": "ANA"
                    },
                    {
                        "label": "Intensivmedizin (ICU)",
                        "value": "ICU"
                    },
                    {
                        "label": "Notaufnahme (ZNA)",
                        "value": "ZNA"
                    },
                    {
                        "label": "Radiologie (RAD)",
                        "value": "RAD"
                    },
                    {
                        "label": "Gynaekologie/Geburtshilfe (GYN)",
                        "value": "GYN"
                    },
                    {
                        "label": "Paediatrie (PAED)",
                        "value": "PAED"
                    },
                    {
                        "label": "Psychiatrie (PSY)",
                        "value": "PSY"
                    }
                ],
                "token": "dept",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        }
    },
    "dataSources": {
        "ds_audit": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:kis:audit\" department=\"$dept$\"\n| fields Zeit _time action break_the_glass btg_reason count department h m patient_id result role user ward workstation",
                "enableSmartSources": true
            },
            "name": "KIS-Audit"
        },
        "ds_k_btg": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_audit",
                "query": "| where break_the_glass=\"true\" OR break_the_glass=1 | timechart span=1h count as \"Break-the-Glass\""
            }
        },
        "ds_k_fail": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_audit",
                "query": "| where result=\"Fehlgeschlagen\" | timechart span=1h count as \"KIS-Logins fehlgeschlagen\""
            }
        },
        "ds_k_win": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"WinEventLog\" EventCode=4625 | timechart span=1h count as \"Windows 4625\"",
                "enableSmartSources": true
            }
        },
        "ds_k_lock": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"WinEventLog\" EventCode=4740 | stats count as Kontosperren",
                "enableSmartSources": true
            }
        },
        "ds_k_net": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"cisco:ios\" \"LOGIN_SUCCESS\" NOT \"Source: 10.\" | stats count as \"Externe Geraete-Logins\"",
                "enableSmartSources": true
            }
        },
        "ds_k_psirt": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"cisco:iq:advisory\" severity=\"Critical\" earliest=-7h | stats dc(hostname) as \"PSIRT kritisch\"",
                "enableSmartSources": true
            }
        },
        "ds_btg": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_audit",
                "query": "| where break_the_glass=\"true\" OR break_the_glass=1\n| eval Zeit=strftime(_time, \"%d.%m. %H:%M\") | table Zeit user role department ward workstation patient_id btg_reason\n| rename user as Benutzer role as Rolle department as Abteilung ward as Station workstation as Arbeitsplatz patient_id as Patient btg_reason as Begruendung"
            }
        },
        "ds_logins": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_audit",
                "query": "| where action=\"Login\" | timechart span=30m count by result"
            }
        },
        "ds_win": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"WinEventLog\" (EventCode=4625 OR EventCode=4740 OR EventCode=4672)\n| rex \"Account Name:\\\\s+(?<account>\\\\S+)\" | rex \"Source Network Address:\\\\s+(?<src>\\\\S+)\"\n| stats count as Anzahl latest(_time) as t by EventCode account src ComputerName\n| eval Zeit=strftime(t, \"%d.%m. %H:%M\"), Ereignis=case(EventCode=4625, \"Anmeldung fehlgeschlagen\", EventCode=4740, \"Konto gesperrt\", true(), \"Privilegierte Anmeldung\")\n| sort - Anzahl | head 25 | table Zeit Ereignis account src ComputerName Anzahl | rename account as Konto src as Quelle ComputerName as Server",
                "enableSmartSources": true
            }
        },
        "ds_netlogin": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"cisco:ios\" (\"LOGIN_SUCCESS\" OR \"CONFIG_P\" OR \"WEBUI\") | rex \"^<\\d+>\\d+: (?<device>[^:]+): [^%]+%(?<facility>[A-Z0-9_]+)-(?<severity>\\d)-(?<mnemonic>[A-Z0-9_]+): (?<message_text>.*)\"\n| rex \"\\\\[user: (?<user>[^\\\\]]+)\\\\] \\\\[Source: (?<src>[^\\\\]]+)\\\\]\"\n| eval Zeit=strftime(_time, \"%d.%m. %H:%M:%S\"), Bewertung=if(isnotnull(src) AND NOT cidrmatch(\"10.0.0.0/8\", src), \"verdaechtig\", \"intern\")\n| table Zeit device mnemonic user src Bewertung message_text | rename device as Geraet user as Benutzer src as Quelle message_text as Meldung | head 30",
                "enableSmartSources": true
            }
        },
        "ds_ssh": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"syslog\" \"Failed password\" | rex \"from (?<src>\\\\S+) port\" | timechart span=1h count by host",
                "enableSmartSources": true
            }
        },
        "ds_psirt": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"cisco:iq:advisory\" earliest=-7h | stats dc(hostname) as Geraete by severity advisoryId | sort severity | rename severity as Schwere advisoryId as Advisory",
                "enableSmartSources": true
            }
        },
        "ds_inc": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"snow:incident\" category=\"Security\" | stats latest(state) as Status latest(priority_label) as Prioritaet latest(short_description) as Beschreibung latest(opened_at) as Eroeffnet by number | rename number as Incident",
                "enableSmartSources": true
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_klinik/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_klinik",
                        "dashboard": "kis_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_care": {
            "type": "splunk.image",
